  private var seed = 2463534242L

  private fun nextRandom(): Long {
    seed = seed xor ((seed shl 13) and 0xFFFFFFFFL)
    seed = seed xor (seed ushr 17)
    seed = seed xor ((seed shl 5) and 0xFFFFFFFFL)
    return seed
  }

  // The edge row draws its decimals from EDGE: ±0, NaN, ±INF, .5 ties, a tiny normal.
  private var edge = false

  private fun nv(): Double {
    val r = nextRandom()
    if (edge) return EDGE[(r % EDGE.size).toInt()]
    return ((r % 200001) - 100000) / 10000.0 * SCALES[((r ushr 24) % 7).toInt()]
  }

  // The finite edge values, for the float -> int members (EDGE_FINITE_ONLY in the generator).
  private fun nvf(): Double = EDGE_FINITE[(nextRandom() % EDGE_FINITE.size).toInt()]

  private fun ri(): Int = ((nextRandom() % 60001) - 30000).toInt()

  private fun rnz(): Int = ri().let { if (it == 0) 1 else it }

  private fun rs(): Int = (nextRandom() % 6).toInt()

  private fun rl(): Long = nextRandom()

  private fun rb(): Boolean = (nextRandom() and 1L) == 1L

  private fun rotation2D(x: Vector2, origin: Vector2): Transform2D =
    Transform2D(x, x.orthogonal(), origin)

  private val hashes = linkedMapOf<String, Long>()

  private fun mixBits(name: String, bits: Long) {
    hashes[name] = ((hashes[name] ?: 2166136261L) xor bits) * 16777619L and 0xFFFFFFFFL
  }

  private fun mixLong(name: String, value: Long) {
    mixBits(name, value and 0xFFFFFFFFL)
    mixBits(name, (value ushr 32) and 0xFFFFFFFFL)
  }

  private fun mix(name: String, value: Any?) {
    when (value) {
      null -> mixLong(name, -1L)
      is Double -> mixLong(name, if (value.isNaN()) 0x7FF8000000000000L else value.toRawBits())
      is Long -> mixLong(name, value)
      is Int -> mixLong(name, value.toLong())
      is Boolean -> mixLong(name, if (value) 1L else 0L)
      is String -> value.forEach { mixLong(name, it.code.toLong()) }
      is RID -> mixLong(name, value.value)
      is Vector2 -> listOf(value.x, value.y).forEach { mix(name, it) }
      is Vector3 -> listOf(value.x, value.y, value.z).forEach { mix(name, it) }
      is Vector4 -> listOf(value.x, value.y, value.z, value.w).forEach { mix(name, it) }
      is Quaternion -> listOf(value.x, value.y, value.z, value.w).forEach { mix(name, it) }
      is Color -> listOf(value.r, value.g, value.b, value.a).forEach { mix(name, it) }
      is Vector2i -> listOf(value.x, value.y).forEach { mix(name, it) }
      is Vector3i -> listOf(value.x, value.y, value.z).forEach { mix(name, it) }
      is Vector4i -> listOf(value.x, value.y, value.z, value.w).forEach { mix(name, it) }
      is Rect2 -> listOf(value.position, value.size).forEach { mix(name, it) }
      is Rect2i -> listOf(value.position, value.size).forEach { mix(name, it) }
      is AABB -> listOf(value.position, value.size).forEach { mix(name, it) }
      is Plane -> listOf(value.normal, value.d).forEach { mix(name, it) }
      is Basis -> listOf(value.x, value.y, value.z).forEach { mix(name, it) }
      is Transform2D -> listOf(value.x, value.y, value.origin).forEach { mix(name, it) }
      is Transform3D -> listOf(value.basis, value.origin).forEach { mix(name, it) }
      is Projection -> listOf(value.x, value.y, value.z, value.w).forEach { mix(name, it) }
      is List<*> -> value.forEach { mix(name, it) }
      else -> error("no parity mix for ${value::class}")
    }
  }

  private fun summary(): String =
    hashes.entries.joinToString(" ") { (name, hash) ->
      "${name.replace(' ', '_')}=${hash.toString(16)}"
    }

  private fun report(line: String) {
    System.err.println("[kanama:kt] BuiltinParity kotlin $line")
  }

  private companion object {
    val SCALES = doubleArrayOf(0.001, 0.01, 0.1, 1.0, 10.0, 100.0, 1000.0)
    val EDGE =
      doubleArrayOf(
        0.0,
        -0.0,
        Double.NaN,
        Double.POSITIVE_INFINITY,
        Double.NEGATIVE_INFINITY,
        0.5,
        -0.5,
        1.5,
        2.5,
        -2.5,
        1e-30,
        3.0,
      )
    val EDGE_FINITE = doubleArrayOf(0.0, -0.0, 0.5, -0.5, 1.5, 2.5, -2.5, 1e-30, 3.0)
  }
}
